-- B3 private booking and messaging read projections
CREATE OR REPLACE FUNCTION public.get_my_bookings(p_role text DEFAULT 'client') RETURNS TABLE (id uuid,user_id uuid,guruba_id uuid,service_id uuid,scheduled_at timestamptz,status text,is_reviewed boolean,proposed_time timestamptz,confirmation_deadline timestamptz,platform_fee numeric,meeting_link text,location_lat numeric,location_lng numeric,location_address text,is_custom_booking boolean,is_online boolean,booking_note text,created_at timestamptz,services jsonb,gurubas jsonb,profiles jsonb) LANGUAGE plpgsql SECURITY INVOKER SET search_path=public,pg_temp AS $$ DECLARE v_guruba_id uuid; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF; IF p_role NOT IN ('client','guruba') THEN RAISE EXCEPTION 'Invalid role'; END IF; IF p_role='guruba' THEN SELECT g.id INTO v_guruba_id FROM public.gurubas g WHERE g.user_id=auth.uid(); IF v_guruba_id IS NULL THEN RETURN; END IF; END IF; RETURN QUERY SELECT b.id,b.user_id,b.guruba_id,b.service_id,b.scheduled_at,b.status,b.is_reviewed,b.proposed_time,b.confirmation_deadline,b.platform_fee,b.meeting_link,b.location_lat,b.location_lng,b.location_address,b.is_custom_booking,b.is_online,b.booking_note,b.created_at,CASE WHEN s.id IS NULL THEN NULL ELSE jsonb_build_object('id',s.id,'title',s.title,'description',s.description,'duration_minutes',s.duration_minutes,'base_price',s.base_price,'image_url',s.image_url,'category',s.category,'is_featured',s.is_featured,'is_online_enabled',s.is_online_enabled) END,CASE WHEN g.id IS NULL THEN NULL ELSE jsonb_build_object('id',g.id,'user_id',g.user_id,'bio',g.bio,'years_experience',g.years_experience,'rating',g.rating,'review_count',g.review_count,'location',g.location,'specialties',g.specialties,'is_verified',g.is_verified,'guruba_type',g.guruba_type,'languages',g.languages,'profiles',CASE WHEN p.id IS NULL THEN NULL ELSE jsonb_build_object('id',p.id,'full_name',p.full_name,'avatar_url',p.avatar_url,'latitude',p.latitude,'longitude',p.longitude,'address',p.address) END) END,CASE WHEN p2.id IS NULL THEN NULL ELSE jsonb_build_object('id',p2.id,'full_name',p2.full_name,'email',p2.email,'role',p2.role,'avatar_url',p2.avatar_url,'phone',p2.phone) END FROM public.bookings b LEFT JOIN public.services s ON s.id=b.service_id LEFT JOIN public.gurubas g ON g.id=b.guruba_id LEFT JOIN public.profiles p ON p.id=g.user_id LEFT JOIN public.profiles p2 ON p2.id=b.user_id WHERE (p_role='client' AND b.user_id=auth.uid()) OR (p_role='guruba' AND b.guruba_id=v_guruba_id) ORDER BY b.scheduled_at ASC NULLS LAST,b.created_at DESC; END; $$;
REVOKE ALL ON FUNCTION public.get_my_bookings(text) FROM public,anon; GRANT EXECUTE ON FUNCTION public.get_my_bookings(text) TO authenticated;
CREATE OR REPLACE FUNCTION public.get_my_message_users() RETURNS TABLE(id uuid,email text,full_name text,role text,phone text,avatar_url text,city text,credits numeric) LANGUAGE sql SECURITY INVOKER SET search_path=public,pg_temp AS $$ WITH ids AS (SELECT DISTINCT CASE WHEN m.sender_id=auth.uid() THEN m.receiver_id ELSE m.sender_id END id FROM public.messages m WHERE m.sender_id=auth.uid() OR m.receiver_id=auth.uid()) SELECT p.id,p.email,p.full_name,p.role,p.phone,p.avatar_url,p.city,p.credits FROM public.profiles p JOIN ids ON ids.id=p.id; $$;
REVOKE ALL ON FUNCTION public.get_my_message_users() FROM public,anon; GRANT EXECUTE ON FUNCTION public.get_my_message_users() TO authenticated;
CREATE OR REPLACE FUNCTION public.get_my_messages(p_other_user_id uuid,p_booking_id uuid DEFAULT NULL) RETURNS SETOF public.messages LANGUAGE sql SECURITY INVOKER SET search_path=public,pg_temp AS $$ SELECT m.* FROM public.messages m WHERE ((m.sender_id=auth.uid() AND m.receiver_id=p_other_user_id) OR (m.sender_id=p_other_user_id AND m.receiver_id=auth.uid())) AND (p_booking_id IS NULL OR m.booking_id=p_booking_id) ORDER BY m.created_at ASC; $$;
REVOKE ALL ON FUNCTION public.get_my_messages(uuid,uuid) FROM public,anon; GRANT EXECUTE ON FUNCTION public.get_my_messages(uuid,uuid) TO authenticated;